<?php

declare(strict_types=1);

namespace Runalyze\Model\Activity\Splits;

/**
 * Generated by hand
 */
final class SplitTest extends \PHPUnit\Framework\TestCase
{
    public function testStringConstructor(): void
    {
        $Split = new Split('R1.00|4:20');

        $this->assertEqualsWithDelta(1.00, $Split->distance(), PHP_FLOAT_EPSILON);
        $this->assertSame(260, $Split->time());
        $this->assertFalse($Split->isActive());
    }

    public function testParameterConstructor(): void
    {
        $Split = new Split(1.00, 260, false);

        $this->assertEqualsWithDelta(1.00, $Split->distance(), PHP_FLOAT_EPSILON);
        $this->assertSame(260, $Split->time());
        $this->assertFalse($Split->isActive());
    }

    public function testSetter(): void
    {
        $Split = new Split();

        $this->assertTrue($Split->isEmpty());
        $this->assertTrue($Split->isActive());

        $Split->setDistance(1.00);
        $Split->setTime(300);
        $Split->setResting();

        $this->assertFalse($Split->isEmpty());
        $this->assertEqualsWithDelta(1.00, $Split->distance(), PHP_FLOAT_EPSILON);
        $this->assertSame(300, $Split->time());
        $this->assertFalse($Split->isActive());
    }
}
